package com.estoqueinteligente.report;
import com.estoqueinteligente.product.*;import java.util.*;import org.springframework.stereotype.Service;
@Service public class ReportService{private final ProductService products;public ReportService(ProductService p){products=p;}public List<StockReportResponse> stock(){return products.findAll().stream().map(StockReportResponse::new).toList();}public List<LowStockReportResponse> lowStock(){return products.findLowStock().stream().map(LowStockReportResponse::new).toList();}public List<ExpiringReportResponse> expiring(){return List.of();}public List<ExpiredReportResponse> expired(){return List.of();}public List<PurchaseSuggestionResponse> purchaseSuggestion(){return products.findLowStock().stream().map(PurchaseSuggestionResponse::new).toList();}}
